import{_ as a,o as i,c as e,aj as l}from"./framework.js";const k=JSON.parse('{"title":"持续同步 | Cli / Workflows | Documentation","description":"持续同步 in Kooboo: kb sync 会持续监听当前项目中的站点资源。文件新增、修改或删除后，CLI 会把对应变化写入远端站点。","frontmatter":{"title":"持续同步 | Cli / Workflows | Documentation","description":"持续同步 in Kooboo: kb sync 会持续监听当前项目中的站点资源。文件新增、修改或删除后，CLI 会把对应变化写入远端站点。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cli/workflows/sync.html"}]]},"headers":[],"relativePath":"zh/cli/workflows/sync.md","filePath":"cli/workflows/sync.md","lastUpdated":1784361314000}'),t={name:"zh/cli/workflows/sync.md"};function n(h,s,o,p,d,c){return i(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="持续同步" tabindex="-1">持续同步 <a class="header-anchor" href="#持续同步" aria-label="Permalink to &quot;持续同步&quot;">​</a></h1><p><code>kb sync</code> 会持续监听当前项目中的站点资源。文件新增、修改或删除后，CLI 会把对应变化写入远端站点。</p><h2 id="启动同步" tabindex="-1">启动同步 <a class="header-anchor" href="#启动同步" aria-label="Permalink to &quot;启动同步&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span></code></pre></div><p>如果项目的 <code>package.json</code> 将 <code>dev</code> 配置为 <code>kb sync</code>，也可以运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>启动成功后，进程会持续运行。保持终端打开，按 <code>Ctrl+C</code> 停止监听。</p><h2 id="首次初始化同步" tabindex="-1">首次初始化同步 <a class="header-anchor" href="#首次初始化同步" aria-label="Permalink to &quot;首次初始化同步&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span></span></code></pre></div><p>普通 <code>kb sync</code> 只处理监听开始后的变化。<code>--init</code> 会在启动时同时处理资源目录中已有的文件，因此可能一次修改大量远端资源。</p><p>首次初始化前，建议先执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>确认本地项目确实应该成为目标站点的资源来源后，再运行 <code>kb sync --init</code>。</p><h2 id="临时指定连接信息" tabindex="-1">临时指定连接信息 <a class="header-anchor" href="#临时指定连接信息" aria-label="Permalink to &quot;临时指定连接信息&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --site-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --username</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-username</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-password</span></span></code></pre></div><p>命令参数只影响本次同步。日常开发仍建议使用项目 <code>.env</code>，减少误连站点的风险。</p><h2 id="同步共享模块文件" tabindex="-1">同步共享模块文件 <a class="header-anchor" href="#同步共享模块文件" aria-label="Permalink to &quot;同步共享模块文件&quot;">​</a></h2><p>需要把一个公共目录镜像到项目中的各个模块时，可以指定：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --common-module-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../common-module</span></span></code></pre></div><p>公共目录的新增、修改和删除会同步到各模块对应位置，并继续按正常资源流程写入远端。使用前确认模块之间确实应共享同一份文件。</p><h2 id="远端影响" tabindex="-1">远端影响 <a class="header-anchor" href="#远端影响" aria-label="Permalink to &quot;远端影响&quot;">​</a></h2><p>同步进程会处理：</p><ul><li>新增文件：创建或更新远端资源；</li><li>修改文件：覆盖对应远端资源；</li><li>删除文件：删除对应远端资源；</li><li>Page 和 API：需要有效的 <code>@k-url</code>；</li><li>不支持的扩展名：不会作为对应资源保存。</li></ul><p>停止 <code>kb sync</code> 只会停止后续监听，不会撤销已经写入远端的修改。</p><h2 id="与-pushignore-的区别" tabindex="-1">与 <code>.pushignore</code> 的区别 <a class="header-anchor" href="#与-pushignore-的区别" aria-label="Permalink to &quot;与 \`.pushignore\` 的区别&quot;">​</a></h2><p><code>.pushignore</code> 只影响 <code>kb push</code>。<code>kb sync</code> 不读取 <code>.pushignore</code>。</p><p>如果某些文件不应同步：</p><ul><li>不要把它们放入 CLI 监听的资源目录；</li><li>修改临时文件前先停止 <code>kb sync</code>；</li><li>使用单独的源码或构建目录，再把最终产物复制到资源目录。</li></ul><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ul><li>纯本地编辑时不要保持 <code>kb sync</code> 常驻；</li><li>需要远端实时联调时再启动；</li><li>同一项目不要同时运行多个同步进程；</li><li>切换站点前先停止同步，再修改 <code>.env</code>；</li><li>大范围重命名或删除前先提交 Git，以便审查和恢复。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../project/resources.html">项目资源与目录</a></li><li><a href="./push.html">推送本地资源</a></li><li><a href="./check-and-prune.html">资源对账与远端清理</a></li></ul>`,32)])])}const u=a(t,[["render",n]]);export{k as __pageData,u as default};
